window.TRIGGLE_CLASSES=window.TRIGGLE_CLASSES||{};window.TRIGGLE_CLASSES[9]={"chapters":{"1":{"en":"Set Language","ta":"கணங்களின் மொழி"},"2":{"en":"Real Numbers","ta":"மெய்யெண்கள்"},"3":{"en":"Algebra","ta":"இயற்கணிதம்"},"4":{"en":"Geometry","ta":"வடிவியல்"},"5":{"en":"Coordinate Geometry","ta":"ஆயத்தொலைவு வடிவியல்"},"6":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"7":{"en":"Mensuration","ta":"அளவியல்"},"8":{"en":"Statistics","ta":"புள்ளியியல்"},"9":{"en":"Probability","ta":"நிகழ்தகவு"}},"items":[{"id":"c9-example-6-1","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Example 6.1","ta":"எடுத்துக்காட்டு 6.1"},"title":{"en":"The 12–35–37 triangle","ta":"The 12–35–37 triangle"},"q":{"en":"Using the labelled right triangle, determine sin θ, cos θ and tan θ.","ta":"கொடுக்கப்பட்ட செங்கோண முக்கோணத்தில் sin θ, cos θ, tan θ ஆகியவற்றைக் காண்க."},"steps":[{"en":"From the diagram, the opposite side measures 35, the adjacent side measures 12, and the hypotenuse measures 37.","ta":"படத்தில் எதிர்ப்பக்கம் 35, அடுத்துள்ள பக்கம் 12, கர்ணம் 37.","eq":"35² + 12² = 1225 + 144 = 1369 = 37²"},{"en":"Sine compares the opposite side with the hypotenuse.","ta":"சைன் என்பது எதிர்ப்பக்கத்தை கர்ணத்தால் வகுத்த விகிதம்.","eq":"sin θ = [[35|37]]"},{"en":"Cosine compares the adjacent side with the hypotenuse.","ta":"கோசைன் என்பது அடுத்துள்ள பக்கத்தை கர்ணத்தால் வகுத்த விகிதம்.","eq":"cos θ = [[12|37]]"},{"en":"Tangent compares the opposite side with the adjacent side.","ta":"டேன்ஜென்ட் என்பது எதிர்ப்பக்கத்தை அடுத்துள்ள பக்கத்தால் வகுத்த விகிதம்.","eq":"tan θ = [[35|12]]"}],"answer":"sin θ = [[35|37]] ; cos θ = [[12|37]] ; tan θ = [[35|12]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":35,"adj":12,"hyp":"37","angle":"θ"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":3},{"id":"c9-example-6-2","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Example 6.2","ta":"எடுத்துக்காட்டு 6.2"},"title":{"en":"Use Pythagoras before finding six ratios","ta":"Use Pythagoras before finding six ratios"},"q":{"en":"In a right triangle, the side opposite θ is 7 and the hypotenuse is 25. Find all six ratios at θ.","ta":"θ-க்கு எதிர்ப்பக்கம் 7, கர்ணம் 25 உள்ள செங்கோண முக்கோணத்தில் ஆறு முக்கோணவியல் விகிதங்களையும் காண்க."},"steps":[{"en":"Use Pythagoras to find the adjacent side before forming any ratio.","ta":"முதலில் பிதாகரஸ் தேற்றத்தால் அடுத்துள்ள பக்கத்தைக் காண்க.","eq":"Adjacent = √(25² − 7²) = √(625 − 49) = √576 = 24"},{"en":"Write sine, cosine, and tangent in that order, using opposite 7, adjacent 24, and hypotenuse 25.","ta":"எதிர்ப்பக்கம் 7, அடுத்துள்ள பக்கம் 24, கர்ணம் 25 என்பதைப் பயன்படுத்தி sin, cos, tan-ஐ அதே வரிசையில் எழுதுக.","eq":"sin θ = [[7|25]] ; cos θ = [[24|25]] ; tan θ = [[7|24]]"},{"en":"Take their reciprocals in the same order: cosecant, secant, and cotangent.","ta":"அவற்றின் தலைகீழ் விகிதங்களான cosec, sec, cot-ஐ அதே வரிசையில் எழுதுக.","eq":"cosec θ = [[25|7]] ; sec θ = [[25|24]] ; cot θ = [[24|7]]"}],"answer":"sin θ = [[7|25]] ; cos θ = [[24|25]] ; tan θ = [[7|24]] ; cosec θ = [[25|7]] ; sec θ = [[25|24]] ; cot θ = [[24|7]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":7,"adj":24,"hyp":"25","angle":"θ"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":4},{"id":"c9-example-6-3","classNum":9,"chapter":"6","exercise":"6.3","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Example 6.3","ta":"எடுத்துக்காட்டு 6.3"},"title":{"en":"Given tangent, recover the five other ratios","ta":"Given tangent, recover the five other ratios"},"q":{"en":"Given tan A = [[2|3]], determine all remaining trigonometric ratios.","ta":"tan A = [[2|3]] எனில், மீதமுள்ள முக்கோணவியல் விகிதங்களைக் காண்க."},"steps":[{"en":"Treat tangent as opposite over adjacent. Choose sides 2 and 3.","ta":"tan என்பது எதிர்ப்பக்கம் / அடுத்துள்ள பக்கம். பக்கங்களை 2, 3 என எடுத்துக்கொள்க.","eq":"tan A = [[2|3]]"},{"en":"Use Pythagoras to calculate the hypotenuse.","ta":"கர்ணத்தைப் பிதாகரஸ் தேற்றத்தால் காண்க.","eq":"AC = √(2² + 3²) = √13"},{"en":"Write sine and cosine using the side lengths.","ta":"பக்க அளவுகளிலிருந்து sin மற்றும் cos-ஐ எழுதுக.","eq":"sin A = [[2|√13]] ; cos A = [[3|√13]]"},{"en":"Take reciprocals and use adjacent over opposite for cotangent.","ta":"தலைகீழ் விகிதங்களையும் cot-க்கான அடுத்துள்ள / எதிர்ப்பக்க விகிதத்தையும் எழுதுக.","eq":"cosec A = [[√13|2]] ; sec A = [[√13|3]] ; cot A = [[3|2]]"}],"answer":"sin A = [[2|√13]] ; cos A = [[3|√13]] ; cosec A = [[√13|2]] ; sec A = [[√13|3]] ; cot A = [[3|2]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":2,"adj":3,"hyp":"√13","angle":"A"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":5},{"id":"c9-example-6-4","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Example 6.4","ta":"எடுத்துக்காட்டு 6.4"},"title":{"en":"Evaluate an expression from secant","ta":"Evaluate an expression from secant"},"q":{"en":"When sec θ = [[13|5]], determine the value of [[2 sin θ − 3 cos θ|4 sin θ − 9 cos θ]].","ta":"sec θ = [[13|5]] எனில் [[2 sin θ − 3 cos θ|4 sin θ − 9 cos θ]]-ன் மதிப்பைக் காண்க."},"steps":[{"en":"Secant means hypotenuse divided by adjacent. Set those lengths to 13 and 5.","ta":"sec என்பது கர்ணம் / அடுத்துள்ள பக்கம். அவற்றை 13, 5 என எடுத்துக்கொள்க.","eq":"sec θ = [[13|5]]"},{"en":"Find the remaining opposite side using Pythagoras.","ta":"மீதமுள்ள எதிர்ப்பக்கத்தைப் பிதாகரஸ் தேற்றத்தால் காண்க.","eq":"Opposite = √(13² − 5²) = √144 = 12"},{"en":"Calculate the two ratios in the order they occur in the question.","ta":"கேள்வியில் உள்ள வரிசைப்படி sin மற்றும் cos-ஐ கணக்கிடுக.","eq":"sin θ = [[12|13]] ; cos θ = [[5|13]]"},{"en":"Each term has denominator 13; cancel that common factor from the numerator and denominator of the original fraction.","ta":"எல்லா உறுப்புகளிலும் உள்ள பொதுவான 13 என்ற வகுத்தெண்ணை எளிமைப்படுத்துக.","eq":"[[2 sin θ − 3 cos θ|4 sin θ − 9 cos θ]] = [[2 × 12 − 3 × 5|4 × 12 − 9 × 5]]"},{"en":"Now simplify the numerator and denominator without changing their order.","ta":"தொகுதி மற்றும் பகுதியின் வரிசையை மாற்றாமல் எளிமைப்படுத்துக.","eq":"[[24 − 15|48 − 45]] = [[9|3]] = 3"}],"answer":"3","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":12,"adj":5,"hyp":"13","angle":"θ"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":5},{"id":"c9-exercise-6-1-q1","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q1","ta":"பயிற்சி 6.1 · வினா 1"},"title":{"en":"Six ratios from the given diagram","ta":"Six ratios from the given diagram"},"q":{"en":"The diagram identifies AB = 40, AC = 9 and BC = 41, with a right angle at A. Determine all six ratios at B.","ta":"படத்தில் AB = 40, AC = 9, BC = 41 மற்றும் A-வில் செங்கோணம். B கோணத்தின் ஆறு விகிதங்களைக் காண்க."},"steps":[{"en":"At B, AC is opposite, AB is adjacent, and BC is the hypotenuse.","ta":"B-ஐப் பொறுத்து AC எதிர்ப்பக்கம், AB அடுத்துள்ள பக்கம், BC கர்ணம்.","eq":"Opposite = 9 ; Adjacent = 40 ; Hypotenuse = 41"},{"en":"First calculate sine, cosine and tangent.","ta":"முதலில் sin, cos, tan-ஐ காண்க.","eq":"sin B = [[9|41]] ; cos B = [[40|41]] ; tan B = [[9|40]]"},{"en":"Invert these fractions for cosecant, secant and cotangent.","ta":"அவற்றைத் தலைகீழாக்கி cosec, sec, cot-ஐ காண்க.","eq":"cosec B = [[41|9]] ; sec B = [[41|40]] ; cot B = [[40|9]]"}],"answer":"sin B = [[9|41]] ; cos B = [[40|41]] ; tan B = [[9|40]] ; cosec B = [[41|9]] ; sec B = [[41|40]] ; cot B = [[40|9]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":9,"adj":40,"hyp":"41","angle":"B"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q2","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q2","ta":"பயிற்சி 6.1 · வினா 2"},"title":{"en":"Two right triangles, six requested values","ta":"Two right triangles, six requested values"},"q":{"en":"In the figure, AB = 13, BD = 5, DC = 16 and AD is perpendicular to BC. Calculate the three ratios at B and the three at C.","ta":"படத்தில் AB = 13, BD = 5, DC = 16; AD ⟂ BC. B-இல் மூன்று விகிதங்களையும் C-இல் மூன்று விகிதங்களையும் காண்க."},"steps":[{"en":"Apply Pythagoras in triangle ABD to find the common height AD.","ta":"ABD முக்கோணத்தில் பிதாகரஸ் தேற்றத்தால் AD உயரத்தைக் காண்க.","eq":"AD = √(13² − 5²) = √144 = 12"},{"en":"Find the hypotenuse AC of the second right triangle ADC.","ta":"ADC முக்கோணத்தின் AC கர்ணத்தைக் காண்க.","eq":"AC = √(12² + 16²) = √400 = 20"},{"en":"In triangle ABD, use opposite 12, adjacent 5, hypotenuse 13.","ta":"ABD-இல் எதிர்ப்பக்கம் 12, அடுத்துள்ள பக்கம் 5, கர்ணம் 13.","eq":"sin B = [[12|13]] ; sec B = [[13|5]] ; cot B = [[5|12]]"},{"en":"In triangle ADC, use opposite 12, adjacent 16, hypotenuse 20.","ta":"ADC-இல் எதிர்ப்பக்கம் 12, அடுத்துள்ள பக்கம் 16, கர்ணம் 20.","eq":"cos C = [[16|20]] = [[4|5]] ; tan C = [[12|16]] = [[3|4]] ; cosec C = [[20|12]] = [[5|3]]"}],"answer":"sin B = [[12|13]] ; sec B = [[13|5]] ; cot B = [[5|12]] ; cos C = [[4|5]] ; tan C = [[3|4]] ; cosec C = [[5|3]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"two-triangles"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q3","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q3","ta":"பயிற்சி 6.1 · வினா 3"},"title":{"en":"Six ratios given cosine","ta":"Six ratios given cosine"},"q":{"en":"For an acute angle θ, if 2cos θ = √3, find all six trigonometric ratios of θ.","ta":"θ ஒரு குறுங்கோணம்; 2cos θ = √3 எனில் ஆறு விகிதங்களையும் காண்க."},"steps":[{"en":"Isolate cosine by dividing both sides by 2.","ta":"இரு பக்கங்களையும் 2-ஆல் வகுத்து cos θ-ஐ தனியாகப் பெறுக.","eq":"cos θ = [[√3|2]]"},{"en":"For an acute angle, this is the 30° special-angle triangle.","ta":"குறுங்கோணத்திற்கு இது 30°-க்கான சிறப்புக் கோணம்.","eq":"θ = 30° ; sin θ = [[1|2]]"},{"en":"Tangent is sine over cosine.","ta":"tan என்பது sin / cos.","eq":"tan θ = [[1|√3]]"},{"en":"The reciprocal ratios are the inverted versions.","ta":"மீதமுள்ளவை அவற்றின் தலைகீழ் விகிதங்கள்.","eq":"cosec θ = 2 ; sec θ = [[2|√3]] ; cot θ = √3"}],"answer":"sin θ = [[1|2]] ; cos θ = [[√3|2]] ; tan θ = [[1|√3]] ; cosec θ = 2 ; sec θ = [[2|√3]] ; cot θ = √3","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":1,"adj":1.73205,"hyp":"2","angle":"30°"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q4","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q4","ta":"பயிற்சி 6.1 · வினா 4"},"title":{"en":"Evaluate the expression from cos A","ta":"Evaluate the expression from cos A"},"q":{"en":"Given cos A = [[3|5]], find [[sin A − cos A|2 tan A]].","ta":"cos A = [[3|5]] எனில் [[sin A − cos A|2 tan A]]-ன் மதிப்பைக் காண்க."},"steps":[{"en":"Cosine is adjacent over hypotenuse. A 3–4–5 right triangle has opposite side 4.","ta":"cos = அடுத்துள்ள பக்கம் / கர்ணம். 3–4–5 முக்கோணத்தின் எதிர்ப்பக்கம் 4.","eq":"Opposite = √(5² − 3²) = 4"},{"en":"Find sine and tangent for angle A.","ta":"A கோணத்திற்கான sin மற்றும் tan-ஐ காண்க.","eq":"sin A = [[4|5]] ; tan A = [[4|3]]"},{"en":"Work out the original numerator, sin A − cos A, in that order.","ta":"முதலில் கேள்வியில் உள்ள தொகுதி sin A − cos A-ஐ அதே வரிசையில் கணக்கிடுக.","eq":"sin A − cos A = [[4|5]] − [[3|5]] = [[1|5]]"},{"en":"Work out the original denominator, 2 tan A.","ta":"அடுத்து பகுதி 2 tan A-ஐ காண்க.","eq":"2 tan A = 2 × [[4|3]] = [[8|3]]"},{"en":"Finally divide numerator by denominator, using the reciprocal rule.","ta":"பகுதியின் தலைகீழ் விகிதத்தால் பெருக்கி இறுதியாக வகுக்கவும்.","eq":"[[1|5]] ÷ [[8|3]] = [[1|5]] × [[3|8]] = [[3|40]]"}],"answer":"[[3|40]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":4,"adj":3,"hyp":"5","angle":"A"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q5","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q5","ta":"பயிற்சி 6.1 · வினா 5"},"title":{"en":"Ratios in terms of x","ta":"Ratios in terms of x"},"q":{"en":"If cos A = [[2x|1 + x²]], find sin A and tan A. Assume A is acute, so x > 0 and x ≠ 1.","ta":"cos A = [[2x|1 + x²]] எனில் sin A, tan A-ஐ காண்க. A ஒரு குறுங்கோணம்; x > 0, x ≠ 1 என எடுத்துக்கொள்க."},"steps":[{"en":"In a right triangle, take adjacent = 2x and hypotenuse = 1+x².","ta":"அடுத்துள்ள பக்கம் = 2x, கர்ணம் = 1+x² என எடுத்துக்கொள்க.","eq":"cos A = [[2x|1+x²]]"},{"en":"Calculate the opposite side using Pythagoras. A length cannot be negative.","ta":"பிதாகரஸ் தேற்றத்தால் எதிர்ப்பக்கத்தைக் காண்க. பக்க நீளம் எதிர்மறையாக இருக்க முடியாது.","eq":"√((1+x²)² − (2x)²) = √((1−x²)²) = |1−x²|"},{"en":"Sine compares opposite and hypotenuse.","ta":"sin = எதிர்ப்பக்கம் / கர்ணம்.","eq":"sin A = [[∣1−x²∣|1+x²]]"},{"en":"Tangent compares opposite and adjacent.","ta":"tan = எதிர்ப்பக்கம் / அடுத்துள்ள பக்கம்.","eq":"tan A = [[∣1−x²∣|2x]]"},{"en":"For 0<x<1, remove the absolute bars as 1−x². For x>1, use x²−1.","ta":"0<x<1 எனில் தனி மதிப்புக் குறிகளை நீக்கலாம்; x>1 எனில் x²−1 பயன்படுத்துக.","eq":"0<x<1: sin A = [[1−x²|1+x²]] ; tan A = [[1−x²|2x]]"}],"answer":"sin A = [[∣1−x²∣|1+x²]] ; tan A = [[∣1−x²∣|2x]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"symbolic-x"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q6","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q6","ta":"பயிற்சி 6.1 · வினா 6"},"title":{"en":"Prove the relation involving a and b","ta":"Prove the relation involving a and b"},"q":{"en":"Starting from sin θ = [[a|√(a² + b²)]], show that b sin θ = a cos θ.","ta":"sin θ = [[a|√(a² + b²)]] எனில் b sin θ = a cos θ என்பதை நிரூபிக்கவும்."},"steps":[{"en":"Choose a positive right triangle whose opposite side is a and adjacent side is b.","ta":"எதிர்ப்பக்கம் a, அடுத்துள்ள பக்கம் b கொண்ட செங்கோண முக்கோணத்தை எடுத்துக்கொள்க.","eq":"Hypotenuse = √(a² + b²)"},{"en":"Write the adjacent-over-hypotenuse ratio.","ta":"cos-க்கான அடுத்துள்ள / கர்ண விகிதத்தை எழுதுக.","eq":"cos θ = [[b|√(a² + b²)]]"},{"en":"Multiply each ratio by the other side and compare.","ta":"இரு விகிதங்களையும் மற்றொரு பக்கத்தால் பெருக்கி ஒப்பிடுக.","eq":"b sin θ = [[ab|√(a² + b²)]]"},{"en":"The expression on the right simplifies to the same fraction.","ta":"வலப்பக்கமும் அதே பின்னமாக எளிமையாகிறது.","eq":"a cos θ = [[ab|√(a² + b²)]] = b sin θ"}],"answer":"b sin θ = a cos θ","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"symbolic"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q7","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q7","ta":"பயிற்சி 6.1 · வினா 7"},"title":{"en":"Solve using a cotangent relation","ta":"Solve using a cotangent relation"},"q":{"en":"Given 3 cot A = 2, calculate [[4 sin A − 3 cos A|2 sin A + 3 cos A]].","ta":"3 cot A = 2 எனில் [[4 sin A − 3 cos A|2 sin A + 3 cos A]]-ன் மதிப்பைக் காண்க."},"steps":[{"en":"Divide 3 cot A = 2 by 3.","ta":"இருபக்கங்களையும் 3-ஆல் வகுக்கவும்.","eq":"cot A = [[2|3]]"},{"en":"Take adjacent = 2 and opposite = 3. The hypotenuse is √13.","ta":"அடுத்துள்ள பக்கம் 2, எதிர்ப்பக்கம் 3; கர்ணம் √13.","eq":"sin A = [[3|√13]] ; cos A = [[2|√13]]"},{"en":"Keep the original numerator in the same order: 4 sin A − 3 cos A.","ta":"கேள்வியில் உள்ள தொகுதி 4 sin A − 3 cos A வரிசையைக் காக்கவும்.","eq":"4 sin A − 3 cos A = [[4 × 3 − 3 × 2|√13]] = [[6|√13]]"},{"en":"Now calculate the original denominator: 2 sin A + 3 cos A.","ta":"பகுதி 2 sin A + 3 cos A-ஐக் கணக்கிடுக.","eq":"2 sin A + 3 cos A = [[2 × 3 + 3 × 2|√13]] = [[12|√13]]"},{"en":"Divide the numerator by the denominator and cancel their shared √13 factor.","ta":"வகுக்கும்போது பொதுவான √13 காரணியை நீக்குக.","eq":"[[6|√13]] ÷ [[12|√13]] = [[6|12]] = [[1|2]]"}],"answer":"[[1|2]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":3,"adj":2,"hyp":"√13","angle":"A"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q8","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q8","ta":"பயிற்சி 6.1 · வினா 8"},"title":{"en":"Simplify using a ratio of cosine to sine","ta":"Simplify using a ratio of cosine to sine"},"q":{"en":"When cos θ : sin θ = 1 : 2, calculate [[8 cos θ − 2 sin θ|4 cos θ + 2 sin θ]].","ta":"cos θ : sin θ = 1 : 2 எனில் [[8 cos θ − 2 sin θ|4 cos θ + 2 sin θ]]-ஐக் காண்க."},"steps":[{"en":"The ratio cos θ : sin θ = 1 : 2 means adjacent : opposite = 1 : 2.","ta":"கொடுக்கப்பட்ட விகிதம் அடுத்துள்ள பக்கம் : எதிர்ப்பக்கம் = 1 : 2 எனப் பொருள்.","eq":"Adjacent = 1 ; Opposite = 2 ; Hypotenuse = √5"},{"en":"Write cosine and sine in the same order as the given ratio.","ta":"கொடுத்த வரிசையில் cos மற்றும் sin-ஐ எழுதுக.","eq":"cos θ = [[1|√5]] ; sin θ = [[2|√5]]"},{"en":"First calculate the numerator, 8 cos θ − 2 sin θ.","ta":"தொகுதி 8 cos θ − 2 sin θ-ஐ முதலில் கணக்கிடுக.","eq":"8 cos θ − 2 sin θ = [[8 × 1 − 2 × 2|√5]] = [[4|√5]]"},{"en":"Next calculate the denominator, 4 cos θ + 2 sin θ.","ta":"பிறகு பகுதி 4 cos θ + 2 sin θ-ஐ கணக்கிடுக.","eq":"4 cos θ + 2 sin θ = [[4 × 1 + 2 × 2|√5]] = [[8|√5]]"},{"en":"The common factor √5 cancels when we divide.","ta":"வகுக்கும்போது பொதுவான √5 காரணி நீங்கும்.","eq":"[[4|√5]] ÷ [[8|√5]] = [[4|8]] = [[1|2]]"}],"answer":"[[1|2]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":2,"adj":1,"hyp":"√5","angle":"θ"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q9","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q9","ta":"பயிற்சி 6.1 · வினா 9"},"title":{"en":"A larger triangle formed by two smaller ones","ta":"A larger triangle formed by two smaller ones"},"q":{"en":"The diagram has AD=9, DB=16, CD=12, AC=15 and BC=20. Prove θ+φ=90°, show ∠ACB=90°, and find sinα, cosβ and tanφ.","ta":"படத்தில் AD=9, DB=16, CD=12, AC=15, BC=20. θ+φ=90°, ∠ACB=90° என நிரூபித்து sinα, cosβ, tanφ காண்க."},"steps":[{"en":"Triangles ACD and BCD are right-angled at D. Their sides satisfy Pythagoras.","ta":"ACD, BCD ஆகியவை D-இல் செங்கோண முக்கோணங்கள்; பிதாகரஸ் தேற்றம் பொருந்தும்.","eq":"9² + 12² = 15² ; 16² + 12² = 20²"},{"en":"The complete triangle ABC is also right angled at C, because its sides are 15, 20 and 25.","ta":"ABC-இல் பக்கங்கள் 15, 20, 25 என்பதால் C-இலும் செங்கோணம் உள்ளது.","eq":"15² + 20² = 25² ; ∠ACB = 90°"},{"en":"The angle at C is split by CD, so the two marked parts are complementary.","ta":"C கோணம் CD மூலம் இரண்டாகப் பிரிகிறது; அவை நிரப்புக் கோணங்கள்.","eq":"θ + φ = 90°"},{"en":"For α in triangle ACD, opposite = CD = 12, hypotenuse = AC = 15.","ta":"ACD-இல் α-க்கு எதிர்ப்பக்கம் CD=12, கர்ணம் AC=15.","eq":"sin α = [[12|15]] = [[4|5]]"},{"en":"For β in triangle BCD, adjacent = DB = 16, hypotenuse = BC = 20.","ta":"BCD-இல் β-க்கு அடுத்துள்ள பக்கம் DB=16, கர்ணம் BC=20.","eq":"cos β = [[16|20]] = [[4|5]]"},{"en":"For φ at C in triangle BCD, opposite = DB = 16 and adjacent = CD = 12.","ta":"C-இல் φ-க்கு எதிர்ப்பக்கம் DB=16, அடுத்துள்ள பக்கம் CD=12.","eq":"tan φ = [[16|12]] = [[4|3]]"}],"answer":"θ+φ = 90° ; ∠ACB = 90° ; sin α = [[4|5]] ; cos β = [[4|5]] ; tan φ = [[4|3]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"two-right"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":6},{"id":"c9-exercise-6-1-q10","classNum":9,"chapter":"6","exercise":"6.1","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.1 · Q10","ta":"பயிற்சி 6.1 · வினா 10"},"title":{"en":"Kite height after extending the string","ta":"Kite height after extending the string"},"q":{"en":"A kite string initially measures 25 m and reaches a height of 5 m. The same straight line is extended another 10 m. Find the final vertical height.","ta":"பட்டக் கயிறு முதலில் 25 m நீளத்தில் 5 m உயரத்தை அடைகிறது. அதே திசையில் மேலும் 10 m நீட்டினால் புதிய உயரம் என்ன?"},"steps":[{"en":"The two right triangles share the same elevation angle, so their height-to-string ratios are equal.","ta":"இரு முக்கோணங்களிலும் ஏற்றக் கோணம் ஒன்றே; உயரம் / கயிறு விகிதமும் ஒன்றே.","eq":"sin θ = [[5|25]] = [[1|5]]"},{"en":"The total new length of string is 25 m + 10 m.","ta":"புதிய கயிறின் மொத்த நீளத்தைக் கணக்கிடுக.","eq":"OQ = 35 m"},{"en":"Use the unchanged sine ratio for the second triangle.","ta":"இரண்டாவது முக்கோணத்திலும் அதே sin விகிதத்தைப் பயன்படுத்துக.","eq":"[[h|35]] = [[1|5]]"},{"en":"Multiply both sides by 35 m. The new kite height is 7 m.","ta":"இருபக்கங்களையும் 35 m-ஆல் பெருக்குக; புதிய உயரம் 7 m.","eq":"h = [[35|5]] = 7 m"}],"answer":"7 m","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"kite"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":7},{"id":"c9-exercise-6-2-q1-i","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q1(i)","ta":"பயிற்சி 6.2 · வினா 1(i)"},"title":{"en":"Verify sine squared plus cosine squared at 60°","ta":"Verify sine squared plus cosine squared at 60°"},"q":{"en":"Verify: sin²60° + cos²60° = 1.","ta":"sin²60° + cos²60° = 1 என்பதைச் சரிபார்க்கவும்."},"steps":[{"en":"Take the exact special-angle values.","ta":"சிறப்புக் கோணத்தின் சரியான மதிப்புகளை எடுத்துக்கொள்க.","eq":"sin 60° = [[√3|2]] ; cos 60° = [[1|2]]"},{"en":"Square each and add.","ta":"ஒவ்வொன்றையும் வர்க்கப்படுத்திக் கூட்டுக.","eq":"sin² 60° + cos² 60° = [[3|4]] + [[1|4]]"},{"en":"The total is 1, so the equality holds.","ta":"கூட்டுத்தொகை 1 என்பதால் சமன்பாடு சரி.","eq":"[[3 + 1|4]] = 1"}],"answer":"LHS = RHS = 1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":60},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q1-ii","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q1(ii)","ta":"பயிற்சி 6.2 · வினா 1(ii)"},"title":{"en":"Verify the tangent–secant identity at 30°","ta":"Verify the tangent–secant identity at 30°"},"q":{"en":"Verify: 1 + tan²30° = sec²30°.","ta":"1 + tan²30° = sec²30° என்பதைச் சரிபார்க்கவும்."},"steps":[{"en":"At 30°, tangent and secant are known exactly.","ta":"30°-இல் tan, sec ஆகியவற்றின் துல்லிய மதிப்புகளை அறிக.","eq":"tan 30° = [[1|√3]] ; sec 30° = [[2|√3]]"},{"en":"Calculate the left-hand side.","ta":"இடப்பக்கத்தை கணக்கிடுக.","eq":"1 + tan²30° = 1 + [[1|3]] = [[4|3]]"},{"en":"Calculate the right-hand side.","ta":"வலப்பக்கத்தை தனியாகக் கணக்கிடுக.","eq":"sec²30° = [[4|3]]"},{"en":"Both sides match.","ta":"இருபக்கங்களும் சமமாக உள்ளன.","eq":"LHS = RHS = [[4|3]]"}],"answer":"LHS = RHS = [[4|3]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q1-iii","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q1(iii)","ta":"பயிற்சி 6.2 · வினா 1(iii)"},"title":{"en":"Three forms give zero","ta":"Three forms give zero"},"q":{"en":"Verify: cos90° = 1 − 2sin²45° = 2cos²45° − 1.","ta":"cos90° = 1 − 2sin²45° = 2cos²45° − 1 என்பதைச் சரிபார்க்கவும்."},"steps":[{"en":"The cosine of 90° is zero.","ta":"cos90°-ன் மதிப்பு பூஜ்யம்.","eq":"cos 90° = 0"},{"en":"Use sin45° = cos45° = 1 over √2.","ta":"sin45° = cos45° = 1/√2 பயன்படுத்துக.","eq":"1 − 2 sin²45° = 1 − 2 × [[1|2]] = 0"},{"en":"Check the cosine form too.","ta":"cos உள்ள வடிவத்தையும் சரிபார்க்கவும்.","eq":"2 cos²45° − 1 = 2 × [[1|2]] − 1 = 0"},{"en":"All expressions agree.","ta":"எல்லா வடிவங்களும் சமமானவை.","eq":"0 = 0 = 0"}],"answer":"0 = 0 = 0","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q1-iv","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q1(iv)","ta":"பயிற்சி 6.2 · வினா 1(iv)"},"title":{"en":"A sine–cosine combination equals one","ta":"A sine–cosine combination equals one"},"q":{"en":"Verify: sin30°cos60° + cos30°sin60° = sin90°.","ta":"sin30°cos60° + cos30°sin60° = sin90° என்பதைச் சரிபார்க்கவும்."},"steps":[{"en":"Recall the four values in the exact order of the left-hand expression.","ta":"இடப்பக்கத்தில் உள்ள நான்கு மதிப்புகளையும் அதே வரிசையில் எடுத்துக்கொள்க.","eq":"sin30° = [[1|2]] ; cos60° = [[1|2]] ; cos30° = [[√3|2]] ; sin60° = [[√3|2]]"},{"en":"Replace each pair in the left-hand side, keeping the two terms in place.","ta":"உறுப்புகளின் வரிசையை மாற்றாமல் மதிப்புகளைப் பதிலிடுக.","eq":"sin30°cos60° + cos30°sin60° = [[1|4]] + [[3|4]] = 1"},{"en":"Evaluate the right-hand side separately and compare.","ta":"வலப்பக்கத்தைக் கணக்கிட்டு ஒப்பிடுக.","eq":"sin90° = 1 ; LHS = RHS = 1"}],"answer":"LHS = RHS = 1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q2-i","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q2(i)","ta":"பயிற்சி 6.2 · வினா 2(i)"},"title":{"en":"Evaluate a three-part expression","ta":"Evaluate a three-part expression"},"q":{"en":"Evaluate: [[tan45°|cosec30°]] + [[sec60°|cot45°]] − [[5sin90°|2cos0°]].","ta":"[[tan45°|cosec30°]] + [[sec60°|cot45°]] − [[5sin90°|2cos0°]] மதிப்பைக் காண்க."},"steps":[{"en":"Replace the six functions with their known values.","ta":"ஆறு விகிதங்களுக்கான சிறப்புக் கோண மதிப்புகளைப் பதிலிடுக.","eq":"[[1|2]] + [[2|1]] − [[5 × 1|2 × 1]]"},{"en":"All terms can be expressed in halves.","ta":"எல்லா உறுப்புகளையும் பின்னங்களாக எழுதலாம்.","eq":"[[1|2]] + [[4|2]] − [[5|2]]"},{"en":"The terms cancel.","ta":"கூட்டலும் கழித்தலும் செய்து எளிமைப்படுத்துக.","eq":"[[1 + 4 − 5|2]] = 0"}],"answer":"0","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q2-ii","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q2(ii)","ta":"பயிற்சி 6.2 · வினா 2(ii)"},"title":{"en":"Multiply complementary expressions","ta":"Multiply complementary expressions"},"q":{"en":"Evaluate: (sin90° + cos60° + cos45°) × (sin30° + cos0° − cos45°).","ta":"(sin90° + cos60° + cos45°) × (sin30° + cos0° − cos45°) மதிப்பைக் காண்க."},"steps":[{"en":"Substitute into each bracket without changing its term order.","ta":"ஒவ்வொரு அடைப்புக்குறிக்குள்ளும் அசல் வரிசையைக் காக்கும் வகையில் மதிப்புகளைப் பதிலிடுக.","eq":"(1 + [[1|2]] + [[1|√2]]) × ([[1|2]] + 1 − [[1|√2]])"},{"en":"Combine the first two numbers in each bracket. The brackets become conjugates.","ta":"முதல் இரு எண்களைக் கூட்டினால் (a+b), (a−b) வடிவங்கள் கிடைக்கும்.","eq":"([[3|2]] + [[1|√2]]) × ([[3|2]] − [[1|√2]])"},{"en":"For (a + b)(a − b), multiply to obtain a² − b².","ta":"(a+b)(a−b) = a²−b² என்ற விதியைப் பயன்படுத்துக.","eq":"[[9|4]] − [[1|2]]"},{"en":"Subtract the fractions.","ta":"பின்னங்களைக் கழிக்கவும்.","eq":"[[9 − 2|4]] = [[7|4]]"}],"answer":"[[7|4]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q2-iii","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q2(iii)","ta":"பயிற்சி 6.2 · வினா 2(iii)"},"title":{"en":"Evaluate powers of trigonometric ratios","ta":"Evaluate powers of trigonometric ratios"},"q":{"en":"Evaluate: sin²30° − 2cos³60° + 3tan⁴45°.","ta":"sin²30° − 2cos³60° + 3tan⁴45° மதிப்பைக் காண்க."},"steps":[{"en":"The values are one half, one half and one.","ta":"மதிப்புகள் முறையே 1/2, 1/2, 1.","eq":"sin30° = [[1|2]] ; cos60° = [[1|2]] ; tan45° = 1"},{"en":"Substitute powers carefully.","ta":"அடுக்குகளைக் கவனமாகக் கணக்கிட்டு பதிலிடுக.","eq":"[[1|4]] − 2 × [[1|8]] + 3 × 1"},{"en":"Simplify to the final value.","ta":"இறுதி மதிப்பை எளிமைப்படுத்துக.","eq":"[[1|4]] − [[1|4]] + 3 = 3"}],"answer":"3","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q3","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q3","ta":"பயிற்சி 6.2 · வினா 3"},"title":{"en":"Check a triple-angle identity at 30°","ta":"Check a triple-angle identity at 30°"},"q":{"en":"Verify: cos3A = 4cos³A − 3cos A, when A=30°.","ta":"A=30° எனில் cos3A = 4cos³A − 3cos A என்பதைச் சரிபார்க்கவும்."},"steps":[{"en":"First find the left-hand side.","ta":"முதலில் இடப்பக்கத்தைக் கணக்கிடுக.","eq":"cos(3 × 30°) = cos90° = 0"},{"en":"Then evaluate the right-hand expression using cos30°.","ta":"பிறகு cos30° பயன்படுத்தி வலப்பக்கத்தைக் கணக்கிடுக.","eq":"4 × ( [[√3|2]] )³ − 3 × [[√3|2]]"},{"en":"The two terms are equal and cancel.","ta":"வலப்பக்க உறுப்புகள் ஒன்றை ஒன்று நீக்குகின்றன.","eq":"[[3√3|2]] − [[3√3|2]] = 0"},{"en":"Both sides equal zero.","ta":"இருபக்கங்களும் பூஜ்யம்.","eq":"LHS = RHS = 0"}],"answer":"LHS = RHS = 0","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-2-q4","classNum":9,"chapter":"6","exercise":"6.2","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.2 · Q4","ta":"பயிற்சி 6.2 · வினா 4"},"title":{"en":"Evaluate three angles at x = 15°","ta":"Evaluate three angles at x = 15°"},"q":{"en":"Evaluate: 8sin2x cos4x sin6x, when x=15°.","ta":"x=15° எனில் 8sin2x cos4x sin6x மதிப்பைக் காண்க."},"steps":[{"en":"Find each angle first.","ta":"முதலில் ஒவ்வொரு கோணத்தையும் காண்க.","eq":"2x = 30° ; 4x = 60° ; 6x = 90°"},{"en":"Substitute the exact sine and cosine values.","ta":"sin, cos-ன் துல்லிய மதிப்புகளைப் பதிலிடுக.","eq":"8 × [[1|2]] × [[1|2]] × 1"},{"en":"Multiply step by step.","ta":"வரிசையாகப் பெருக்குக.","eq":"8 × [[1|4]] = 2"}],"answer":"2","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":11},{"id":"c9-exercise-6-3-q-i","classNum":9,"chapter":"6","exercise":"6.3","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.3 · Q1(i)","ta":"பயிற்சி 6.3 · வினா 1(i)"},"title":{"en":"Use complement pairs inside squared fractions","ta":"Use complement pairs inside squared fractions"},"q":{"en":"Evaluate: ([[cos47°|sin43°]])² + ([[sin72°|cos18°]])² − 2cos²45°.","ta":"([[cos47°|sin43°]])² + ([[sin72°|cos18°]])² − 2cos²45° மதிப்பைக் காண்க."},"steps":[{"en":"47° + 43° = 90°. Hence cos47° = sin43°, so their ratio is 1.","ta":"47°+43°=90°; எனவே cos47° = sin43°. முதல் விகிதம் 1.","eq":"[[cos47°|sin43°]] = 1"},{"en":"72° + 18° = 90°. Hence sin72° = cos18°, so this ratio is also 1.","ta":"72°+18°=90°; எனவே sin72° = cos18°. இரண்டாம் விகிதமும் 1.","eq":"[[sin72°|cos18°]] = 1"},{"en":"At 45°, cos45° = 1/√2; its square is 1/2. The coefficient 2 is part of the textbook question.","ta":"cos45°=1/√2; அதன் வர்க்கம் 1/2. கேள்வியில் 2 என்ற பெருக்கல் காரணி உள்ளது.","eq":"2cos²45° = 2 × [[1|2]] = 1"},{"en":"Substitute all three terms, keeping both outer squares.","ta":"இரண்டு அடைப்புக்குறிகளின் வெளிப்புற வர்க்கங்களையும் காக்கும் வகையில் மதிப்புகளைப் பதிலிடுக.","eq":"1² + 1² − 1 = 1"}],"answer":"1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"complement-pairs","pairs":[[47,43],[72,18],[45,45]]},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":14},{"id":"c9-exercise-6-3-q-ii","classNum":9,"chapter":"6","exercise":"6.3","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.3 · Q1(ii)","ta":"பயிற்சி 6.3 · வினா 1(ii)"},"title":{"en":"Four complementary substitutions","ta":"Four complementary substitutions"},"q":{"en":"Evaluate: [[cos70°|sin20°]] + [[cos59°|sin31°]] + [[cos θ|sin(90°−θ)]] − 8cos²60°.","ta":"[[cos70°|sin20°]] + [[cos59°|sin31°]] + [[cos θ|sin(90°−θ)]] − 8cos²60° மதிப்பைக் காண்க."},"steps":[{"en":"Each numerator matches its denominator: 70°+20°=90°, 59°+31°=90°, and sin(90°−θ)=cosθ.","ta":"ஒவ்வொரு விகிதத்திலும் தொகுதியும் பகுதியும் சமம்; நிரப்புக் கோண விதியைப் பயன்படுத்துக.","eq":"[[cos70°|sin20°]] = 1 ; [[cos59°|sin31°]] = 1 ; [[cos θ|sin(90° − θ)]] = 1"},{"en":"Cosine of 60° is 1/2; square before multiplying by eight.","ta":"cos60°=1/2; எட்டால் பெருக்குவதற்கு முன் வர்க்கப்படுத்துக.","eq":"8cos²60° = 8 × [[1|4]] = 2"},{"en":"Add and subtract exactly the terms in the question.","ta":"கேள்வியின் வரிசைப்படியே கூட்டிக் கழிக்கவும்.","eq":"1 + 1 + 1 − 2 = 1"}],"answer":"1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"complement-pairs","pairs":[[70,20],[59,31],[60,30]]},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":14},{"id":"c9-exercise-6-3-q-iii","classNum":9,"chapter":"6","exercise":"6.3","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.3 · Q1(iii)","ta":"பயிற்சி 6.3 · வினா 1(iii)"},"title":{"en":"Five tangent factors simplify to one","ta":"Five tangent factors simplify to one"},"q":{"en":"Evaluate: tan15° × tan30° × tan45° × tan60° × tan75°.","ta":"tan15° × tan30° × tan45° × tan60° × tan75° மதிப்பைக் காண்க."},"steps":[{"en":"Start with the five factors in the exact order shown in the question.","ta":"கேள்வியில் கொடுத்த ஐந்து காரணிகளையும் அதே வரிசையில் தொடங்குக.","eq":"tan15° × tan30° × tan45° × tan60° × tan75°"},{"en":"Because these factors are multiplied, we may group complementary angles without changing the product.","ta":"இது பெருக்கல் என்பதால் நிரப்புக் கோணக் காரணிகளைத் தொகுக்கலாம்.","eq":"(tan15° × tan75°) × (tan30° × tan60°) × tan45°"},{"en":"The first pair is 1 because 15° + 75° = 90°.","ta":"15°+75°=90°; எனவே முதல் ஜோடியின் பெருக்கல் 1.","eq":"tan15° × tan75° = 1"},{"en":"The second pair is 1 because 30° + 60° = 90°.","ta":"30°+60°=90°; இரண்டாம் ஜோடியின் பெருக்கலும் 1.","eq":"tan30° × tan60° = [[1|√3]] × √3 = 1"},{"en":"The middle factor is also 1. Multiply all three results.","ta":"மீதமுள்ள tan45° = 1; முடிவுகளையும் பெருக்குக.","eq":"1 × 1 × tan45° = 1 × 1 × 1 = 1"}],"answer":"1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":14},{"id":"c9-exercise-6-3-q-iv","classNum":9,"chapter":"6","exercise":"6.3","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.3 · Q1(iv)","ta":"பயிற்சி 6.3 · வினா 1(iv)"},"title":{"en":"Simplify a composite complementary identity","ta":"Simplify a composite complementary identity"},"q":{"en":"Evaluate [[cot θ|tan(90°−θ)]] + [[cos(90°−θ) tan θ sec(90°−θ)|sin(90°−θ) cot(90°−θ) cosec(90°−θ)]].","ta":"[[cot θ|tan(90°−θ)]] + [[cos(90°−θ) tan θ sec(90°−θ)|sin(90°−θ) cot(90°−θ) cosec(90°−θ)]] மதிப்பைக் காண்க."},"steps":[{"en":"First simplify the fraction at the beginning of the question.","ta":"கேள்வியின் முதல் பின்னத்தை முதலில் எளிமைப்படுத்துக.","eq":"[[cot θ|tan(90° − θ)]] = [[cot θ|cot θ]] = 1"},{"en":"For the numerator of the second fraction, convert only the first and third factors; tan θ stays in the middle.","ta":"இரண்டாவது பின்னத்தின் தொகுதியில் முதல், மூன்றாம் காரணிகளை மட்டும் நிரப்புக் கோணத்தால் மாற்றுக.","eq":"cos(90° − θ) = sin θ ; sec(90° − θ) = cosec θ"},{"en":"For its denominator, convert each factor in the original order.","ta":"பகுதியின் எல்லாக் காரணிகளையும் அசல் வரிசையில் மாற்றுக.","eq":"sin(90° − θ) = cos θ ; cot(90° − θ) = tan θ ; cosec(90° − θ) = sec θ"},{"en":"Use sin θ × cosec θ = 1 to simplify the numerator.","ta":"sin θ × cosec θ = 1 மூலம் தொகுதியை எளிமைப்படுத்துக.","eq":"sin θ × tan θ × cosec θ = tan θ"},{"en":"Use cos θ × sec θ = 1 to simplify the denominator.","ta":"cos θ × sec θ = 1 மூலம் பகுதியை எளிமைப்படுத்துக.","eq":"cos θ × tan θ × sec θ = tan θ"},{"en":"The original expression becomes 1 plus a fraction equal to 1, wherever defined.","ta":"ஆக மொத்தம் 1 + 1; வரையறுக்கப்பட்ட கோணங்களில் மதிப்பு 2.","eq":"1 + [[tan θ|tan θ]] = 2"}],"answer":"2","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":14},{"id":"c9-exercise-6-4-q1-i","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q1(i)","ta":"பயிற்சி 6.4 · வினா 1(i)"},"title":{"en":"Find sine of 49°","ta":"Find sine of 49°"},"q":{"en":"Look up or calculate sin49° to four decimal places.","ta":"sin49° மதிப்பை நான்கு தசம இடங்களுக்கு காண்க."},"steps":[{"en":"The given angle contains 49 degrees and zero extra minutes.","ta":"கொடுக்கப்பட்ட கோணம் 49 டிகிரி, கூடுதல் நிமிடங்கள் இல்லை.","eq":"θ = 49°00′"},{"en":"Find the sine at that angle with the table or calculator.","ta":"அட்டவணை அல்லது கணிப்பான் மூலம் sin மதிப்பைப் பெறுக.","eq":"sin49° ≈ 0.75470958"},{"en":"Round to four decimal places.","ta":"நான்கு தசம இடங்களுக்கு வட்டமிடுக.","eq":"sin49° ≈ 0.7547"}],"answer":"0.7547","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":49},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q1-ii","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q1(ii)","ta":"பயிற்சி 6.4 · வினா 1(ii)"},"title":{"en":"Find cosine of 74°39′","ta":"Find cosine of 74°39′"},"q":{"en":"Evaluate cos74°39′ to four decimal places.","ta":"cos74°39′ மதிப்பை நான்கு தசம இடங்களுக்கு காண்க."},"steps":[{"en":"Convert 39 angular minutes into degrees.","ta":"39 கோண நிமிடங்களை டிகிரியாக மாற்றுக.","eq":"θ = 74° + [[39|60]]° = 74.65°"},{"en":"Evaluate cosine, retaining extra digits before rounding.","ta":"வட்டமிடுவதற்கு முன் கூடுதல் தசம இலக்கங்களுடன் cos-ஐக் கணக்கிடுக.","eq":"cos74.65° ≈ 0.2647146845"},{"en":"Round to four decimal places: the fifth decimal is 1.","ta":"ஐந்தாவது தசம இலக்கம் 1; நான்கு இடங்களுக்கு வட்டமிடுக.","eq":"cos74°39′ ≈ 0.2647"}],"answer":"0.2647","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":74.65},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q1-iii","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q1(iii)","ta":"பயிற்சி 6.4 · வினா 1(iii)"},"title":{"en":"Find tangent of 54°26′","ta":"Find tangent of 54°26′"},"q":{"en":"Find tan54°26′, reporting four decimal places.","ta":"tan54°26′ மதிப்பை நான்கு தசம இடங்களுக்கு காண்க."},"steps":[{"en":"Convert the minutes into a fraction of a degree.","ta":"நிமிடங்களை டிகிரியின் பின்னமாக மாற்றுக.","eq":"θ = 54° + [[26|60]]° = 54.433333…°"},{"en":"Evaluate tangent without rounding the angle first.","ta":"கோணத்தை முன்கூட்டியே வட்டமிடாமல் tan-ஐக் கணக்கிடுக.","eq":"tan54°26′ ≈ 1.3985034441"},{"en":"Four decimal places require looking at the fifth digit.","ta":"ஐந்தாவது இலக்கத்தைப் பார்த்து நான்கு தசம இடங்களுக்கு வட்டமிடுக.","eq":"tan54°26′ ≈ 1.3985"}],"answer":"1.3985","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":54.4333},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q1-iv","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q1(iv)","ta":"பயிற்சி 6.4 · வினா 1(iv)"},"title":{"en":"Find sine of 21°21′","ta":"Find sine of 21°21′"},"q":{"en":"Find sin21°21′ to four decimal places.","ta":"sin21°21′ மதிப்பை நான்கு தசம இடங்களுக்கு காண்க."},"steps":[{"en":"Convert angular minutes into degrees.","ta":"கோண நிமிடங்களை டிகிரியாக மாற்றுக.","eq":"θ = 21° + [[21|60]]° = 21.35°"},{"en":"Calculate sine before rounding.","ta":"வட்டமிடுவதற்கு முன் sin-ஐக் கணக்கிடுக.","eq":"sin21°21′ ≈ 0.3640641460"},{"en":"The fifth decimal digit is 6, so round the fourth decimal up.","ta":"ஐந்தாவது தசம இலக்கம் 6; எனவே நான்காவது இலக்கத்தை உயர்த்துக.","eq":"sin21°21′ ≈ 0.3641"}],"answer":"0.3641","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":21.35},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q1-v","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q1(v)","ta":"பயிற்சி 6.4 · வினா 1(v)"},"title":{"en":"Find cosine of 33°53′","ta":"Find cosine of 33°53′"},"q":{"en":"Find cos33°53′ to four decimal places.","ta":"cos33°53′ மதிப்பை நான்கு தசம இடங்களுக்கு காண்க."},"steps":[{"en":"Convert angular minutes into degrees.","ta":"கோண நிமிடங்களை டிகிரியாக மாற்றுக.","eq":"θ = 33° + [[53|60]]° = 33.883333…°"},{"en":"Calculate cosine before rounding.","ta":"வட்டமிடுவதற்கு முன் cos-ஐக் கணக்கிடுக.","eq":"cos33°53′ ≈ 0.8301744915"},{"en":"The fifth decimal digit is 7, so round the fourth decimal up.","ta":"ஐந்தாவது தசம இலக்கம் 7; எனவே நான்காவது இலக்கத்தை உயர்த்துக.","eq":"cos33°53′ ≈ 0.8302"}],"answer":"0.8302","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":33.8833},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q1-vi","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q1(vi)","ta":"பயிற்சி 6.4 · வினா 1(vi)"},"title":{"en":"Find tangent of 70°17′","ta":"Find tangent of 70°17′"},"q":{"en":"Find tan70°17′ to four decimal places.","ta":"tan70°17′ மதிப்பை நான்கு தசம இடங்களுக்கு காண்க."},"steps":[{"en":"Convert 17 minutes to degrees.","ta":"17 நிமிடங்களை டிகிரியாக மாற்றுக.","eq":"θ = 70° + [[17|60]]° = 70.283333…°"},{"en":"Evaluate tangent without rounding the angle first.","ta":"கோணத்தை முன்கூட்டியே வட்டமிடாமல் tan-ஐக் கணக்கிடுக.","eq":"tan70°17′ ≈ 2.7903338772"},{"en":"Round to four decimal places.","ta":"நான்கு தசம இடங்களுக்கு வட்டமிடுக.","eq":"tan70°17′ ≈ 2.7903"}],"answer":"2.7903","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":70.2833},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q4","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q4","ta":"பயிற்சி 6.4 · வினா 4"},"title":{"en":"Right-triangle area from hypotenuse and angle","ta":"Right-triangle area from hypotenuse and angle"},"q":{"en":"The hypotenuse is 10 cm and an acute angle is 24°24′. Calculate the triangle’s area.","ta":"கர்ணம் 10 cm, ஒரு குறுங்கோணம் 24°24′ எனில் முக்கோணத்தின் பரப்பளவைக் காண்க."},"steps":[{"en":"Use the hypotenuse to find the base and the height.","ta":"கர்ணத்தைப் பயன்படுத்தி அடிப்பக்கம், உயரம் காண்க.","eq":"Base = 10 cos24°24′ ; height = 10 sin24°24′"},{"en":"The triangle-area formula is one half times base times height.","ta":"முக்கோணப் பரப்பளவு = 1/2 × அடிப்பக்கம் × உயரம்.","eq":"Area = [[1|2]] × 10 cos24°24′ × 10 sin24°24′"},{"en":"Evaluate with trigonometric-table approximations.","ta":"முக்கோணவியல் அட்டவணையின் தோராய மதிப்புகளைப் பயன்படுத்துக.","eq":"Area ≈ 18.81 cm²"}],"answer":"18.81 cm²","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":4.131,"adj":9.105,"hyp":"10 cm","angle":"24°24′"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q5","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q5","ta":"பயிற்சி 6.4 · வினா 5"},"title":{"en":"Angle of a ladder leaning against a wall","ta":"Angle of a ladder leaning against a wall"},"q":{"en":"A 5 m ladder rests against a wall, with its foot 4 m from the wall. Find its angle to the ground.","ta":"5 m ஏணி சுவரில் சாய்கிறது. அதன் அடிப்பகுதி சுவரிலிருந்து 4 m தொலைவில் உள்ளது. தரையுடன் உருவாகும் கோணம் என்ன?"},"steps":[{"en":"Adjacent side = 4 m; hypotenuse = 5 m.","ta":"அடுத்துள்ள பக்கம் 4 m; கர்ணம் 5 m.","eq":"cos θ = [[4|5]] = 0.8"},{"en":"Find the angle whose cosine is 0.8.","ta":"cos மதிப்பு 0.8 ஆக இருக்கும் கோணத்தைக் காண்க.","eq":"θ = cos⁻¹(0.8) ≈ 36.8699°"},{"en":"Convert fractional degrees into minutes.","ta":"தசம டிகிரியை நிமிடங்களாக மாற்றுக.","eq":"0.8699 × 60 ≈ 52′"},{"en":"Round to the nearest minute.","ta":"அருகிலுள்ள நிமிடத்திற்கு வட்டமிடுக.","eq":"θ ≈ 36°52′"}],"answer":"36°52′","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"triangle","opp":3,"adj":4,"hyp":"5 m","angle":"θ"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-4-q6","classNum":9,"chapter":"6","exercise":"6.4","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.4 · Q6","ta":"பயிற்சி 6.4 · வினா 6"},"title":{"en":"Height of the tree from an elevation angle","ta":"Height of the tree from an elevation angle"},"q":{"en":"From a point 60 m from the tree, the angle of elevation to its top is 42°. Find the height.","ta":"ஒரு மரத்திலிருந்து 60 m தொலைவில், அதன் உச்சிக்கான ஏற்றக் கோணம் 42° எனில் உயரத்தைக் காண்க."},"steps":[{"en":"The tree is opposite the 42° angle; the ground distance is adjacent.","ta":"42°-க்கு மர உயரம் எதிர்ப்பக்கம்; தரைத் தொலைவு அடுத்துள்ள பக்கம்.","eq":"tan42° = [[height|60]]"},{"en":"Isolate the unknown height.","ta":"தெரியாத உயரத்தைத் தனியாகப் பெறுக.","eq":"height = 60 × tan42°"},{"en":"Substitute tan42° ≈ 0.900404.","ta":"tan42° ≈ 0.900404 என்று பதிலிடுக.","eq":"height ≈ 60 × 0.900404"},{"en":"Round to two decimals.","ta":"இரண்டு தசம இடங்களுக்கு வட்டமிடுக.","eq":"height ≈ 54.02 m"}],"answer":"54.02 m","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"tree"},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-5-q1","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q1","ta":"பயிற்சி 6.5 · வினா 1"},"title":{"en":"Two half-value ratios","ta":"Two half-value ratios"},"q":{"en":"For x = sin30° and y = cos60°, calculate x² + y².","ta":"x = sin30°, y = cos60° எனில் x² + y² காண்க."},"steps":[{"en":"Both values are one half.","ta":"இரு மதிப்புகளும் 1/2.","eq":"x = y = [[1|2]]"},{"en":"Square and add.","ta":"வர்க்கப்படுத்திக் கூட்டுக.","eq":"x² + y² = [[1|4]] + [[1|4]] = [[1|2]]"},{"en":"Select the option containing one half.","ta":"1/2 உள்ள விடையைத் தேர்ந்தெடுக்கவும்.","eq":"Answer = [[1|2]]"}],"answer":"[[1|2]]","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-5-q2","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q2","ta":"பயிற்சி 6.5 · வினா 2"},"title":{"en":"Tangent equals complementary cotangent","ta":"Tangent equals complementary cotangent"},"q":{"en":"If tan θ = cot37°, determine the acute angle θ.","ta":"tan θ = cot37° எனில் குறுங்கோணம் θ-ஐக் காண்க."},"steps":[{"en":"Keep the given left-hand side, and replace cot37° by tangent of its complement.","ta":"இடப்பக்கத்தை அப்படியே வைத்து, cot37°-ஐ அதன் நிரப்புக் கோணத்தின் tan வடிவில் மாற்றுக.","eq":"tan θ = cot37° = tan(90° − 37°)"},{"en":"Calculate the angle inside the tangent.","ta":"tan-க்குள் உள்ள கோணத்தைக் கணக்கிடுக.","eq":"tan θ = tan53°"},{"en":"For acute angles, equal tangent values give equal angles.","ta":"குறுங்கோணங்களில் tan மதிப்புகள் சமமெனில் கோணங்களும் சமம்.","eq":"θ = 53°"}],"answer":"θ = 53°","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":53},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-5-q3","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q3","ta":"பயிற்சி 6.5 · வினா 3"},"title":{"en":"Product of two complementary tangents","ta":"Product of two complementary tangents"},"q":{"en":"Evaluate tan72° × tan18°.","ta":"tan72° × tan18° மதிப்பைக் காண்க."},"steps":[{"en":"The two angles in the question are complementary.","ta":"கேள்வியில் உள்ள இரு கோணங்களும் நிரப்புக் கோணங்கள்.","eq":"72° + 18° = 90°"},{"en":"Use the complementary-angle identity on the FIRST factor.","ta":"முதல் காரணிக்கு மட்டும் நிரப்புக் கோண விதியைப் பயன்படுத்துக.","eq":"tan72° = cot18°"},{"en":"Replace only the first factor; keep tan18° second, exactly as the question does.","ta":"முதல் காரணியை மட்டும் மாற்றி, கேள்விபோல் tan18° இரண்டாவதாகவே இருக்கட்டும்.","eq":"tan72° × tan18° = cot18° × tan18° = 1"}],"answer":"1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":18},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-5-q4","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q4","ta":"பயிற்சி 6.5 · வினா 4"},"title":{"en":"Simplify the doubled-tangent expression","ta":"Simplify the doubled-tangent expression"},"q":{"en":"Find the trigonometric function matching [[2 tan30°|1 − tan²30°]].","ta":"[[2 tan30°|1 − tan²30°]] எந்த முக்கோணவியல் விகிதத்திற்கு சமம்?"},"steps":[{"en":"At 30°, tangent has the exact value 1/√3.","ta":"tan30°-ன் துல்லிய மதிப்பு 1/√3.","eq":"tan30° = [[1|√3]]"},{"en":"Calculate the original numerator first.","ta":"முதலில் அசல் தொகுதியைக் கணக்கிடுக.","eq":"2 tan30° = 2 × [[1|√3]] = [[2|√3]]"},{"en":"Then calculate the original denominator.","ta":"பிறகு அசல் பகுதியைக் கணக்கிடுக.","eq":"1 − tan²30° = 1 − [[1|3]] = [[2|3]]"},{"en":"Divide the numerator by the denominator.","ta":"தொகுதியைப் பகுதியால் வகுக்கவும்.","eq":"[[2|√3]] ÷ [[2|3]] = [[2|√3]] × [[3|2]] = √3"},{"en":"Recognize the trigonometric value asked for.","ta":"கேட்டுள்ள முக்கோணவியல் விகிதத்தைக் கண்டறிக.","eq":"√3 = tan60°"}],"answer":"tan60° = √3","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":18},{"id":"c9-exercise-6-5-q7","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q7","ta":"பயிற்சி 6.5 · வினா 7"},"title":{"en":"Zero from the tangent of 45°","ta":"Zero from the tangent of 45°"},"q":{"en":"Evaluate [[1 − tan²45°|1 + tan²45°]].","ta":"[[1 − tan²45°|1 + tan²45°]] மதிப்பைக் காண்க."},"steps":[{"en":"At 45°, tangent equals one.","ta":"45°-இல் tan மதிப்பு 1.","eq":"tan45° = 1"},{"en":"The numerator becomes zero and the denominator becomes two.","ta":"தொகுதி பூஜ்யம், பகுதி 2 ஆகிறது.","eq":"[[1 − 1²|1 + 1²]] = [[0|2]]"},{"en":"Therefore the expression equals zero.","ta":"ஆகவே பின்னத்தின் மதிப்பு பூஜ்யம்.","eq":"Answer = 0"}],"answer":"0","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":45},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":19},{"id":"c9-exercise-6-5-q8","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q8","ta":"பயிற்சி 6.5 · வினா 8"},"title":{"en":"Two cancelling complementary pairs","ta":"Two cancelling complementary pairs"},"q":{"en":"Simplify cosec(70°+θ) − sec(20°−θ) + tan(65°+θ) − cot(25°−θ).","ta":"cosec(70°+θ) − sec(20°−θ) + tan(65°+θ) − cot(25°−θ) எளிமைப்படுத்துக."},"steps":[{"en":"The first two angles add to 90°, so the first two values are equal.","ta":"முதல் இரண்டு கோணங்கள் 90°-க்கு கூட்டுகின்றன; மதிப்புகள் சமம்.","eq":"cosec(70°+θ) = sec(20°−θ)"},{"en":"The third and fourth angles also add to 90°, so these values are equal.","ta":"மூன்றாம், நான்காம் கோணங்களும் 90°-க்கு கூட்டுகின்றன; இவையும் சமம்.","eq":"tan(65°+θ) = cot(25°−θ)"},{"en":"Subtract each equal pair in the same order as the question.","ta":"கேள்வியின் வரிசைப்படியே சமமான ஒவ்வொரு ஜோடியையும் கழிக்கவும்.","eq":"[cosec(70°+θ) − sec(20°−θ)] + [tan(65°+θ) − cot(25°−θ)] = 0 + 0 = 0"}],"answer":"0","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":null,"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":19},{"id":"c9-exercise-6-5-q9","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q9","ta":"பயிற்சி 6.5 · வினா 9"},"title":{"en":"Pairing tangent values from 1° to 89°","ta":"Pairing tangent values from 1° to 89°"},"q":{"en":"Evaluate tan1° × tan2° × ... × tan89°.","ta":"tan1° × tan2° × … × tan89° மதிப்பைக் காண்க."},"steps":[{"en":"Write the full product in its original ascending order.","ta":"அசல் வரிசையில் எல்லா காரணிகளையும் கருதுக.","eq":"tan1° × tan2° × ⋯ × tan88° × tan89°"},{"en":"Multiplication lets us group the first and last factors, second and second-last, etc., without changing the result.","ta":"பெருக்கலில் முதல்–கடைசி, இரண்டாம்–கடைசிக்கு முந்தையது என ஜோடியாகத் தொகுக்கலாம்.","eq":"(tan1° × tan89°) × (tan2° × tan88°) × ⋯ × tan45°"},{"en":"Each pair multiplies to 1 because its angles total 90°.","ta":"ஒவ்வொரு ஜோடியின் கோணங்கள் 90°-க்கு கூட்டுகின்றன; பெருக்கல் 1.","eq":"tanθ × tan(90°−θ) = 1"},{"en":"The unmatched middle factor is also 1.","ta":"நடுவில் மீதமுள்ள காரணியும் 1.","eq":"tan45° = 1"},{"en":"Every factor group equals 1; therefore the product is 1.","ta":"அனைத்து ஜோடிகளும் 1 என்பதால் மொத்த பெருக்கல் 1.","eq":"Answer = 1"}],"answer":"1","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":null,"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":19},{"id":"c9-exercise-6-5-q10","classNum":9,"chapter":"6","exercise":"6.5","topic":{"en":"Trigonometry","ta":"முக்கோணவியல்"},"label":{"en":"Exercise 6.5 · Q10","ta":"பயிற்சி 6.5 · வினா 10"},"title":{"en":"Sum of two special angles","ta":"Sum of two special angles"},"q":{"en":"Given sin α = [[1|2]] and cos β = [[1|2]], determine α+β for acute angles.","ta":"sin α = [[1|2]], cos β = [[1|2]] எனில் குறுங்கோணங்களின் α+β காண்க."},"steps":[{"en":"Sine equals one half at 30° in the acute-angle range.","ta":"குறுங்கோணங்களில் sin = 1/2 ஆகும் கோணம் 30°.","eq":"α = 30°"},{"en":"Cosine equals one half at 60°.","ta":"cos = 1/2 ஆகும் கோணம் 60°.","eq":"β = 60°"},{"en":"Their sum forms a right angle.","ta":"இரண்டையும் கூட்டினால் செங்கோணம் கிடைக்கும்.","eq":"α + β = 90°"}],"answer":"α + β = 90°","kind":"reference","reference":"Class 9 earlier-edition chapter PDF · exercise numbering may vary","diagram":{"kind":"unitcircle","angle":30},"source":"https://cdn1.byjus.com/wp-content/uploads/2019/04/Tamilnadu-Board-Class-9-Maths-Textbook-Chapter-6-Term-II.pdf","page":19},{"id":"c9-1-1-practice-1","classNum":9,"chapter":"1","exercise":"1.practice","topic":{"en":"Set Language","ta":"கணங்களின் மொழி"},"label":{"en":"Triggle Practice · Set A","ta":"Triggle பயிற்சி · Set A"},"title":{"en":"Set operations","ta":"Set operations"},"q":{"en":"Let A={1,2,3}, B={3,4}. Find A∪B and A∩B.","ta":"A={1,2,3}, B={3,4} எனில் A∪B, A∩B காண்க."},"steps":[{"en":"The union collects unique members from both sets.","ta":"இரு கணங்களிலிருந்தும் தனித்த உறுப்புகளை ஒன்றிணைக்கவும்.","eq":"A∪B={1,2,3,4}"},{"en":"The intersection keeps only shared members.","ta":"இரு கணங்களுக்கும் பொதுவான உறுப்புகளை மட்டும் எடுக்கவும்.","eq":"A∩B={3}"}],"answer":"A∪B={1,2,3,4}; A∩B={3}","kind":"practice","diagram":"sets","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-2-2-practice-2","classNum":9,"chapter":"2","exercise":"2.practice","topic":{"en":"Real Numbers","ta":"மெய்யெண்கள்"},"label":{"en":"Triggle Practice · Real A","ta":"Triggle பயிற்சி · Real A"},"title":{"en":"Surds","ta":"Surds"},"q":{"en":"Simplify √50 − √8.","ta":"√50 − √8 ஐ எளிமைப்படுத்தவும்."},"steps":[{"en":"Take perfect-square factors out of each radical.","ta":"ஒவ்வொரு கரணியிலும் முழு வர்க்கத்தை வெளியே எடுக்கவும்.","eq":"√50=5√2 ; √8=2√2"},{"en":"Subtract the like radicals.","ta":"ஒத்த கரணிகளைக் கழிக்கவும்.","eq":"5√2−2√2=3√2"}],"answer":"3√2","kind":"practice","diagram":"identity","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-3-3-practice-3","classNum":9,"chapter":"3","exercise":"3.practice","topic":{"en":"Algebra","ta":"இயற்கணிதம்"},"label":{"en":"Triggle Practice · Algebra A","ta":"Triggle பயிற்சி · Algebra A"},"title":{"en":"Difference of squares","ta":"Difference of squares"},"q":{"en":"Factorise x² − 9.","ta":"x² − 9 காரணிப்படுத்தவும்."},"steps":[{"en":"Recognise a difference of squares.","ta":"இரு வர்க்கங்களின் வித்தியாசத்தை அறிக.","eq":"x²−9=x²−3²"},{"en":"Use a²−b²=(a−b)(a+b).","ta":"a²−b²=(a−b)(a+b) முற்றொருமையைப் பயன்படுத்தவும்.","eq":"x²−9=(x−3)(x+3)"}],"answer":"(x−3)(x+3)","kind":"practice","diagram":"identity","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-3-3-practice-4","classNum":9,"chapter":"3","exercise":"3.practice","topic":{"en":"Algebra","ta":"இயற்கணிதம்"},"label":{"en":"Triggle Practice · Algebra B","ta":"Triggle பயிற்சி · Algebra B"},"title":{"en":"Linear equation","ta":"Linear equation"},"q":{"en":"Solve 2x + 7 = 19.","ta":"2x+7=19 ஐ தீர்க்கவும்."},"steps":[{"en":"Subtract seven from both sides.","ta":"இரு பக்கங்களிலும் 7 ஐ கழிக்கவும்.","eq":"2x=19−7=12"},{"en":"Divide by two.","ta":"2 ஆல் வகுக்கவும்.","eq":"x=12/2=6"}],"answer":"x=6","kind":"practice","diagram":"identity","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-4-4-practice-5","classNum":9,"chapter":"4","exercise":"4.practice","topic":{"en":"Geometry","ta":"வடிவியல்"},"label":{"en":"Triggle Practice · Angles A","ta":"Triggle பயிற்சி · Angles A"},"title":{"en":"Triangle angles","ta":"Triangle angles"},"q":{"en":"Two angles of a triangle are 55° and 65°. Find the third.","ta":"முக்கோணத்தில் இரு கோணங்கள் 55°, 65°. மூன்றாவது கோணம்?"},"steps":[{"en":"Angles in a triangle total 180°.","ta":"முக்கோணக் கோணங்களின் கூட்டுத்தொகை 180°.","eq":"55°+65°+x=180°"},{"en":"Subtract the known angles.","ta":"தெரிந்த கோணங்களைக் கழிக்கவும்.","eq":"x=180°−120°=60°"}],"answer":"60°","kind":"practice","diagram":"triangle","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-5-5-practice-6","classNum":9,"chapter":"5","exercise":"5.practice","topic":{"en":"Coordinate Geometry","ta":"ஆயத்தொலைவு வடிவியல்"},"label":{"en":"Triggle Practice · Distance A","ta":"Triggle பயிற்சி · Distance A"},"title":{"en":"Coordinate distance","ta":"Coordinate distance"},"q":{"en":"Find the distance between points (0,0) and (3,4).","ta":"(0,0),(3,4) புள்ளிகளுக்கு இடையே உள்ள தொலைவு?"},"steps":[{"en":"Use the two-point distance formula.","ta":"இரு புள்ளித் தொலைவு சூத்திரத்தைப் பயன்படுத்தவும்.","eq":"d=√((3−0)²+(4−0)²)"},{"en":"Simplify inside the radical.","ta":"வர்க்கமூலத்தின் உள்ளே எளிமைப்படுத்தவும்.","eq":"d=√(9+16)=√25=5"}],"answer":"5 units","kind":"practice","diagram":"triangle","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-7-7-practice-7","classNum":9,"chapter":"7","exercise":"7.practice","topic":{"en":"Mensuration","ta":"அளவியல்"},"label":{"en":"Triggle Practice · Area A","ta":"Triggle பயிற்சி · Area A"},"title":{"en":"Rectangle area","ta":"Rectangle area"},"q":{"en":"A rectangle is 12 cm by 7 cm. Find its area.","ta":"12 செமீ நீளமும் 7 செமீ அகலமும் உள்ள செவ்வகத்தின் பரப்பு?"},"steps":[{"en":"The area of a rectangle is length × width.","ta":"செவ்வகப் பரப்பு = நீளம் × அகலம்.","eq":"A=l×w"},{"en":"Substitute the two sides.","ta":"பக்கங்களின் மதிப்புகளை இடவும்.","eq":"A=12×7=84 cm²"}],"answer":"84 cm²","kind":"practice","diagram":"area","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-8-8-practice-8","classNum":9,"chapter":"8","exercise":"8.practice","topic":{"en":"Statistics","ta":"புள்ளியியல்"},"label":{"en":"Triggle Practice · Mean A","ta":"Triggle பயிற்சி · Mean A"},"title":{"en":"Arithmetic mean","ta":"Arithmetic mean"},"q":{"en":"Find the arithmetic mean of 4, 6, 8, 10.","ta":"4,6,8,10 இன் சராசரி காண்க."},"steps":[{"en":"Add the four measurements.","ta":"நான்கு எண்களையும் கூட்டவும்.","eq":"sum=4+6+8+10=28"},{"en":"Divide by the number of observations.","ta":"எண்ணிக்கையால் வகுக்கவும்.","eq":"mean=28/4=7"}],"answer":"7","kind":"practice","diagram":"stats","source":"","reference":"Original Triggle practice — not a numbered textbook question"},{"id":"c9-9-9-practice-9","classNum":9,"chapter":"9","exercise":"9.practice","topic":{"en":"Probability","ta":"நிகழ்தகவு"},"label":{"en":"Triggle Practice · Chance A","ta":"Triggle பயிற்சி · Chance A"},"title":{"en":"Simple probability","ta":"Simple probability"},"q":{"en":"A fair die is rolled. What is P(even)?","ta":"ஒரு சமச்சீர் பகடையை வீசும்போது இரட்டைப்படை எண் வரும் நிகழ்தகவு?"},"steps":[{"en":"Count all equally likely outcomes.","ta":"சமவாய்ப்புள்ள எல்லா முடிவுகளையும் எண்ணவும்.","eq":"{1,2,3,4,5,6}: 6 outcomes"},{"en":"Count favourable even numbers.","ta":"இரட்டைப்படை எண் முடிவுகளை எண்ணவும்.","eq":"{2,4,6}: 3 outcomes"},{"en":"Divide favourable by total.","ta":"சாதக முடிவுகளை மொத்தத்தால் வகுக்கவும்.","eq":"P(even)=3/6=1/2"}],"answer":"1/2","kind":"practice","diagram":"stats","source":"","reference":"Original Triggle practice — not a numbered textbook question"}]};
